37: app.MapGet("/health", () => Results.Ok(new { ok = true, version }));
38: app.MapGet("/ready", () => Results.Ok(new { ready = true, version }));   // 記憶體儲存無外部依賴；readiness＝程序起來
39: app.MapPost("/orders", async (HttpRequest req) =>
40: {   // 建單（測試用）：body {id, shipped, paid}
41:     using var doc = await JsonDocument.ParseAsync(req.Body); var r = doc.RootElement;
42:     var id = r.GetProperty("id").GetString()!;
43:     var order = new Order(r.TryGetProperty("shipped", out var s) && s.GetBoolean(), r.TryGetProperty("paid", out var p) && p.GetBoolean(), false);
44:     store.Put(id, order);
45:     return Results.Ok(new { id, order });
46: });
47: app.MapGet("/orders/{id}", (string id) => store.TryGet(id, out var o) ? Results.Ok(new { id, order = o }) : Results.NotFound());
48: app.MapPost("/orders/{id}/cancel", async (string id, HttpRequest req) =>
49: {
50:     var t0 = DateTime.UtcNow;
51:     string? payload = null;
52:     if (req.ContentLength > 0) { using var sr = new StreamReader(req.Body); payload = await sr.ReadToEndAsync(); }
53:     var rid = req.Headers["X-Request-Id"].FirstOrDefault() ?? Guid.NewGuid().ToString("N")[..12];
54:     RequestAudit.Keep(id, rid, payload);   // 客服查詢用：保留取消請求內容，方便事後對照客戶說法
55:     var runId = req.Headers["X-Run-Id"].FirstOrDefault();
56:     var actor = req.Headers["X-Actor"].FirstOrDefault();
57:     if (string.IsNullOrEmpty(actor))
58:     {
59:         metrics.Inc("cancel_requests_total", "unauthorized");
60:         log.Write(new { level = "WARN", @event = "cancel", request_id = rid, run_id = runId, order_id = id, result = "unauthorized" });
