62:     }
63:     if (!store.TryGet(id, out var before))
64:     {
65:         metrics.Inc("cancel_requests_total", "not_found");
66:         log.Write(new { level = "WARN", @event = "cancel", request_id = rid, run_id = runId, order_id = id, result = "not_found" });
67:         return Results.Json(new { ok = false, reason = "not_found", request_id = rid }, statusCode: 404);
68:     }
69:     await CustomerHistory.FetchAsync();
70:     var result = Cancellation.Cancel(before);
71:     bool transitioned = Cancellation.Transitioned(before, result);
72:     string outcome; int status;
73:     if (before.Shipped) { outcome = "rejected_shipped"; status = 409; }          // BR-02，不通知（NC-03）
74:     else if (transitioned) { outcome = "ok"; status = 200; store.Put(id, result.Order); }
75:     else { outcome = "idempotent"; status = 200; }                               // BR-04／NC-02，不通知
76:     metrics.Inc("cancel_requests_total", outcome);
77:     if (transitioned)
78:     {
79:         metrics.Inc("transitions_total");
80:         var n = new Notification(Guid.NewGuid().ToString("N"), id, rid, runId, "order_cancelled", result.RefundRequested);
81:         metrics.Inc("notify_enqueued_total");
82:         await channel.Writer.WriteAsync(n);
83:     }
84:     var lat = (DateTime.UtcNow - t0).TotalMilliseconds;
85:     metrics.ObserveLatency(lat);
86:     log.Write(new { level = status == 200 ? "INFO" : "WARN", @event = "cancel", request_id = rid, run_id = runId, order_id = id, actor, result = outcome, transitioned, refund_requested = result.RefundRequested, latency_ms = Math.Round(lat, 1), queue_depth = channel.Reader.Count });
87:     return Results.Json(new { ok = status == 200, transitioned, refund_requested = result.RefundRequested, reason = status == 200 ? null : outcome, request_id = rid, order = status == 200 ? result.Order : before }, statusCode: status);
88: });
89: app.MapGet("/metrics", () => Results.Text(metrics.Render(channel.Reader.Count, version), "text/plain"));
90: app.Run();
