101: sealed class Metrics
102: {
103:     readonly Dictionary<string, long> _c = new(); readonly object _g = new();
104:     public void Inc(string name, string? label = null)
105:     {
106:         var k = label is null ? name : name + "{result=\"" + label + "\"}";
107:         lock (_g) _c[k] = _c.GetValueOrDefault(k) + 1;
108:     }
109:     static readonly double[] Buckets = { 5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000 };
110:     readonly long[] _hist = new long[Buckets.Length + 1]; double _latSum; long _latCount;
111:     public void ObserveLatency(double ms)
112:     {
113:         lock (_g) { _latSum += ms; _latCount++; int i = 0; while (i < Buckets.Length && ms > Buckets[i]) i++; _hist[i]++; }
114:     }
115:     public string Render(int depth, string version)
116:     {
117:         lock (_g)
118:         {
119:             var sb = new System.Text.StringBuilder();
120:             foreach (var kv in _c.OrderBy(k => k.Key)) sb.Append("oc_").Append(kv.Key).Append(' ').Append(kv.Value).Append('\n');
121:             sb.Append("oc_notify_queue_depth ").Append(depth).Append('\n');
122:             long cum = 0;
123:             for (int i = 0; i < Buckets.Length; i++) { cum += _hist[i]; sb.Append("oc_request_latency_ms_bucket{le=\"").Append(Buckets[i]).Append("\"} ").Append(cum).Append('\n'); }
124:             cum += _hist[Buckets.Length]; sb.Append("oc_request_latency_ms_bucket{le=\"+Inf\"} ").Append(cum).Append('\n');
125:             sb.Append("oc_request_latency_ms_sum ").Append(Math.Round(_latSum, 1)).Append('\n').Append("oc_request_latency_ms_count ").Append(_latCount).Append('\n');
126:             sb.Append("oc_gc_heap_bytes ").Append(GC.GetTotalMemory(false)).Append('\n');
127:             sb.Append("oc_working_set_bytes ").Append(Environment.WorkingSet).Append('\n');
128:             sb.Append("oc_gc_collections_gen2 ").Append(GC.CollectionCount(2)).Append('\n');
129:             sb.Append("oc_info{version=\"").Append(version).Append("\"} 1\n");
130:             return sb.ToString();
131:         }
132:     }
133: }
