135: sealed class JsonlLog
136: {
137:     readonly string _p; readonly string _v; readonly object _g = new();
138:     public JsonlLog(string p, string v) { _p = p; _v = v; }
139:     public void Write(object o)
140:     {
141:         var d = JsonSerializer.SerializeToNode(o)!.AsObject();
142:         d["ts"] = DateTimeOffset.Now.ToString("o"); d["version"] = _v;
143:         lock (_g) File.AppendAllText(_p, d.ToJsonString() + "\n");
144:     }
145: }
