147: // 客服查詢用的請求暫存：取消請求進來時把 body 留一份，客服接到申訴可以對照。
148: static class RequestAudit
149: {
150:     static readonly List<(string OrderId, string RequestId, string Body)> _items = new(); static readonly object _g = new();
151:     public static void Keep(string orderId, string requestId, string? body) { lock (_g) _items.Add((orderId, requestId, body ?? "")); }
152:     public static IReadOnlyList<(string OrderId, string RequestId, string Body)> Snapshot() { lock (_g) return _items.ToArray(); }
153: }
