155: // 通知 worker：從 channel 取出 → POST sink → 失敗重試 3 次（200／400／800 ms）→ 超過進 dead_letter（NC-05）。
156: sealed class NotificationWorker : BackgroundService
157: {
158:     readonly Channel<Notification> _ch; readonly Metrics _m; readonly JsonlLog _log; readonly HttpClient _http = new();
159:     readonly string _sink = Environment.GetEnvironmentVariable("OC_SINK_URL") ?? "http://127.0.0.1:5081/notify";
160:     static readonly int[] Backoff = { 200, 400, 800 };
161:     const int MaxDeferrals = 5;
162:     public NotificationWorker(Channel<Notification> ch, Metrics m, JsonlLog log) { _ch = ch; _m = m; _log = log; }
163:     static readonly HttpClient SharedHttp = new();
164:     /// 同步送一次（含重試）；計數規則與 worker 相同。
165:     public static async Task SendOnce(Notification n, Metrics m, JsonlLog log, string sink)
166:     {
167:         bool sent = false;
168:         for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
169:         {
170:             try
171:             {
172:                 var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
173:                 var resp = await SharedHttp.PostAsync(sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"));
174:                 sent = resp.IsSuccessStatusCode;
175:             }
176:             catch (Exception e) { log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name }); }
177:             if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt]);
178:         }
179:         if (sent) { m.Inc("notify_sent_total"); log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, sync = true }); }
180:         else { m.Inc("notify_failed_total"); m.Inc("notify_dead_letter_total"); log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 }); }
181:     }
182:     protected override async Task ExecuteAsync(CancellationToken ct)
183:     {
184:         await foreach (var n in _ch.Reader.ReadAllAsync(ct))
185:         {
186:             bool sent = false;
187:             for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
188:             {
189:                 try
190:                 {
191:                     var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
192:                     var resp = await _http.PostAsync(_sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"), ct);
193:                     sent = resp.IsSuccessStatusCode;
194:                     if (!sent) _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, status = (int)resp.StatusCode });
195:                 }
196:                 catch (Exception e) when (!ct.IsCancellationRequested)
197:                 {
198:                     _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name });
199:                 }
200:                 if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt], ct);
201:             }
202:             if (sent)
203:             {
204:                 _m.Inc("notify_sent_total");
205:                 _log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId });
206:             }
207:             else
208:             {
209:                 _m.Inc("notify_failed_total"); _m.Inc("notify_dead_letter_total");
210:                 _log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 });
211:             }
212:         }
213:     }
214: }
