217: static class CustomerHistory
218: {
219:     public static async Task FetchAsync() { await Task.Delay(500); }
220: }
221: static class RuntimeSampler
222: {
223:     public static void Start(string runDir)
224:     {
225:         // Dedicated OS thread: monitoring must not wait for the starving ThreadPool.
226:         var t = new Thread(() => {
227:             using var f = new StreamWriter(Path.Combine(runDir, "runtime.jsonl"));
228:             var proc = System.Diagnostics.Process.GetCurrentProcess();
229:             var sw = System.Diagnostics.Stopwatch.StartNew();
230:             var prev = proc.TotalProcessorTime.TotalMilliseconds; var last = sw.Elapsed.TotalMilliseconds;
231:             while (true) {
232:                 var now = sw.Elapsed.TotalMilliseconds; var cpu = proc.TotalProcessorTime.TotalMilliseconds;
233:                 ThreadPool.GetAvailableThreads(out var available, out var io);
234:                 ThreadPool.GetMaxThreads(out var max, out var maxIo);
235:                 f.WriteLine(JsonSerializer.Serialize(new { elapsed_ms = now, ts = DateTimeOffset.UtcNow,
236:                     threads = ThreadPool.ThreadCount, pending = ThreadPool.PendingWorkItemCount,
237:                     completed = ThreadPool.CompletedWorkItemCount, available, max,
238:                     cpu_core_percent = (cpu-prev)/Math.Max(now-last,1)*100,
239:                     gc_heap_bytes = GC.GetTotalMemory(false), working_set_bytes = Environment.WorkingSet,
240:                     processor_count = Environment.ProcessorCount }));
241:                 f.Flush(); prev=cpu; last=now; Thread.Sleep(100);
242:             }
243:         });
244:         t.IsBackground=true; t.Name="RuntimeSampler"; t.Start();
245:     }
246: }

